-- P34 batch1: authoritative inspection/validation only. No role/assignment mutation RPC.
-- Restore P07 exact-work scopes omitted by P28's expanded fixed-capability check.
alter table public.role_permissions drop constraint role_permissions_check;
alter table public.role_permissions add check(
 (capability='profile.edit_own'and allowed_scope='own')or(capability in('committee.manage','department.review','finance.review','mcd.review','feedback.review')and allowed_scope='unit')or(capability in('workspace.read','directory.read','reports.view','admin.configure','roles.manage')and allowed_scope='term')or(capability='mentoring.view'and allowed_scope='own')or(capability in('workspace.read','committee.manage')and allowed_scope='work'));
create table public.delegation_ceilings(
 id uuid primary key default gen_random_uuid(),term_id uuid not null references public.terms(id),grantor_membership_id uuid not null references public.term_memberships(id),source_assignment_id uuid not null references public.role_assignments(id),source_assignment_version integer not null,source_role_version integer not null,
 capability text not null,scope_type text not null check(scope_type in('own','unit','term','work')),unit_id uuid references public.org_units(id),work_id uuid references public.work_items(id),sensitive_authorized boolean not null default false,
 starts_at timestamptz not null,ends_at timestamptz not null,approved_by uuid not null references public.term_memberships(id),approval_reference text not null check(length(btrim(approval_reference))between 1 and 1000),revoked_at timestamptz,
 check(grantor_membership_id<>approved_by),check(starts_at<ends_at),check((scope_type='unit')=(unit_id is not null)),check((scope_type='work')=(work_id is not null))
);
create table public.verified_app_custodians(
 assignment_id uuid primary key references public.role_assignments(id),assignment_version integer not null,role_version integer not null,verified_by uuid not null references public.term_memberships(id),verification_reference text not null check(length(btrim(verification_reference))between 1 and 1000),verified_at timestamptz not null,effective_to timestamptz not null,revoked_at timestamptz,check(verified_at<effective_to)
);
alter table public.delegation_ceilings enable row level security;alter table public.delegation_ceilings force row level security;
alter table public.verified_app_custodians enable row level security;alter table public.verified_app_custodians force row level security;
revoke all on public.delegation_ceilings,public.verified_app_custodians from public,anon,authenticated,service_role;
create function app_private.access_catalog()returns jsonb language sql immutable set search_path='' as $$
 select jsonb_agg(jsonb_build_object('capability',c,'resource',split_part(c,'.',1),'action',split_part(c,'.',2),'scopes',s,'sensitive',c in('finance.review','mcd.review','feedback.review','admin.configure','roles.manage'))order by c)from(values
 ('workspace.read',array['term','work']),('directory.read',array['term']),('profile.edit_own',array['own']),('committee.manage',array['unit','work']),('department.review',array['unit']),('finance.review',array['unit']),('mcd.review',array['unit']),('feedback.review',array['unit']),('mentoring.view',array['own']),('reports.view',array['term']),('admin.configure',array['term']),('roles.manage',array['term']))v(c,s)
$$;
create function app_private.access_assignment_live(p_assignment uuid)returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.role_assignments a join public.roles r on r.id=a.role_id join public.term_memberships tm on tm.id=a.term_membership_id join public.members m on m.id=tm.member_id join public.terms t on t.id=tm.term_id join public.organizations o on o.id=tm.organization_id where a.id=p_assignment and a.term_id=tm.term_id and r.term_id=a.term_id and r.state='active'and a.status='active'and a.effective_from<=statement_timestamp()and a.effective_to>statement_timestamp()and tm.membership_kind='core'and tm.status='active'and tm.joined_at<=statement_timestamp()and tm.ends_at>statement_timestamp()and m.account_state='active'and t.state in('active','frozen')and o.state='active'and(statement_timestamp()at time zone'Asia/Manila')::date between t.starts_on and t.closes_on and(a.scope_type<>'unit'or exists(select 1 from public.unit_memberships d join public.org_units u on u.id=d.unit_id where d.term_membership_id=tm.id and d.unit_id=a.unit_id and d.status='active'and d.effective_from<=statement_timestamp()and d.effective_to>statement_timestamp()and u.archived_at is null))and(a.scope_type<>'work'or exists(select 1 from public.work_items w where w.id=a.work_id and w.term_id=a.term_id and w.archived_at is null)))
$$;
create function app_private.access_ceiling_live(c public.delegation_ceilings)returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.term_memberships approver where approver.id=c.approved_by and approver.term_id=c.term_id and approver.membership_kind='core')and c.grantor_membership_id=public.current_term_membership(c.term_id)and c.revoked_at is null and c.starts_at<=statement_timestamp()and c.ends_at>statement_timestamp()and exists(select 1 from public.role_assignments a join public.roles r on r.id=a.role_id join public.role_permissions p on p.role_id=a.role_id and p.allowed_scope=a.scope_type and p.capability=c.capability where a.id=c.source_assignment_id and a.term_id=c.term_id and a.term_membership_id=c.grantor_membership_id and a.version=c.source_assignment_version and r.version=c.source_role_version and app_private.access_assignment_live(a.id)and(
 (c.scope_type=a.scope_type and c.unit_id is not distinct from a.unit_id and c.work_id is not distinct from a.work_id)or(c.scope_type='work'and c.capability in('workspace.read','committee.manage')and exists(select 1 from public.work_items w where w.id=c.work_id and w.term_id=c.term_id and w.archived_at is null and public.can_access_work(w.id,'detail')and((a.scope_type='term'and c.capability='workspace.read')or(a.scope_type='unit'and w.lead_unit_id=a.unit_id))))))
$$;
create function app_private.access_editor(p_term uuid)returns public.term_memberships language plpgsql stable security definer set search_path='' as $$declare m public.term_memberships;begin m:=app_private.request_actor(p_term);if not public.has_capability(p_term,'roles.manage')and not exists(select 1 from public.delegation_ceilings c where c.term_id=p_term and c.grantor_membership_id=m.id and app_private.access_ceiling_live(c))then raise exception using errcode='42501',message='command_permission_denied';end if;return m;end$$;
create function app_private.access_verified_custodian(p_assignment uuid)returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.verified_app_custodians v join public.role_assignments a on a.id=v.assignment_id join public.roles r on r.id=a.role_id join public.term_memberships tm on tm.id=a.term_membership_id join public.members m on m.id=tm.member_id where v.assignment_id=p_assignment and a.scope_type='term'and app_private.access_assignment_live(a.id)and v.assignment_version=a.version and v.role_version=r.version and v.revoked_at is null and v.verified_at<=statement_timestamp()and v.effective_to>statement_timestamp()and v.verified_by<>tm.id and exists(select 1 from public.term_memberships verifier where verifier.id=v.verified_by and verifier.term_id=a.term_id and verifier.membership_kind='core')and m.auth_user_id is not null and app_private.verified_google_email(m.auth_user_id)=m.normalized_email and m.normalized_email like '%@student.ateneo.edu'and not exists(select 1 from unnest(array['admin.configure','roles.manage'])cap where not exists(select 1 from public.role_permissions p where p.role_id=r.id and p.capability=cap and p.allowed_scope='term')))
$$;
create function public.preflight_access_change(p_term_id uuid,p_values jsonb)returns jsonb language plpgsql stable security definer set search_path='' as $$
declare m public.term_memberships;recipient public.term_memberships;a public.role_assignments;p record;c public.delegation_ceilings;cap text;scope text;unit uuid;work uuid;starts timestamptz;ends timestamptz;target uuid;constraints jsonb:='[]';covered boolean:=false;eligible boolean:=true;begin
 m:=app_private.access_editor(p_term_id);
 if not app_private.definition_keys(p_values,array['action','targetMembershipId','capability','scope','unitId','workId','from','to','assignmentId'])or(p_values->>'action')is null or(p_values->>'action')not in('grant','revoke')then raise exception using errcode='22023',message='command_validation_failed';end if;
 if p_values->>'action'='revoke'then
 select *into a from public.role_assignments where id=(p_values->>'assignmentId')::uuid and term_id=p_term_id;if not found then return jsonb_build_object('withinCeiling',false,'mutationAvailable',false,'constraints',jsonb_build_array('current_target_assignment_required'));end if;target:=a.term_membership_id;scope:=a.scope_type;unit:=a.unit_id;work:=a.work_id;starts:=statement_timestamp();ends:=a.effective_to;
 if scope='term'and exists(select 1 from public.role_permissions rp where rp.role_id=a.role_id and rp.allowed_scope='term'and rp.capability in('admin.configure','roles.manage'))and not exists(select 1 from public.verified_app_custodians v join public.role_assignments other on other.id=v.assignment_id where other.term_id=p_term_id and other.term_membership_id<>target and app_private.access_verified_custodian(other.id))then constraints:=constraints||jsonb_build_array('verified_custodian_replacement_required');end if;
 else
 target:=(p_values->>'targetMembershipId')::uuid;cap:=p_values->>'capability';scope:=p_values->>'scope';unit:=nullif(p_values->>'unitId','')::uuid;work:=nullif(p_values->>'workId','')::uuid;starts:=(p_values->>'from')::timestamptz;ends:=(p_values->>'to')::timestamptz;
 if target is null or starts is null or ends is null or not isfinite(starts)or not isfinite(ends)or starts>=ends or not exists(select 1 from jsonb_array_elements(app_private.access_catalog())x where x->>'capability'=cap and(x->'scopes')?scope)or(scope='unit')is distinct from(unit is not null)or(scope='work')is distinct from(work is not null)then raise exception using errcode='22023',message='command_validation_failed';end if;
 end if;
 if target=m.id then constraints:=constraints||jsonb_build_array('no_self_privilege_change');end if;
 select *into recipient from public.term_memberships where id=target and term_id=p_term_id and membership_kind='core'and status='active'and joined_at<=statement_timestamp()and ends_at>statement_timestamp();
 if recipient.id is null or not exists(select 1 from public.members where id=recipient.member_id and account_state='active')then constraints:=constraints||jsonb_build_array('active_recipient_required');end if;
 if not exists(select 1 from public.terms where id=p_term_id and state='active')then constraints:=constraints||jsonb_build_array('active_term_required');end if;
 if unit is not null and not exists(select 1 from public.org_units where id=unit and term_id=p_term_id and archived_at is null)then constraints:=constraints||jsonb_build_array('current_unit_required');end if;
 if work is not null and not exists(select 1 from public.work_items w where w.id=work and w.term_id=p_term_id and w.archived_at is null and public.can_access_work(w.id,'detail'))then constraints:=constraints||jsonb_build_array('independent_record_access_required');end if;
 for p in select rp.capability from public.role_permissions rp where p_values->>'action'='revoke'and rp.role_id=a.role_id and rp.allowed_scope=scope union all select cap where p_values->>'action'='grant'loop
 covered:=false;for c in select *from public.delegation_ceilings ceiling where ceiling.term_id=p_term_id and ceiling.grantor_membership_id=m.id and ceiling.capability=p.capability and ceiling.scope_type=scope and ceiling.unit_id is not distinct from unit and ceiling.work_id is not distinct from work loop
 if app_private.access_ceiling_live(c)and(p.capability not in('finance.review','mcd.review','feedback.review','admin.configure','roles.manage')or c.sensitive_authorized)and(p_values->>'action'='revoke'or(starts>=c.starts_at and ends<=c.ends_at and starts>=recipient.joined_at and ends<=recipient.ends_at and ends<=(select effective_to from public.role_assignments where id=c.source_assignment_id)and ends<=(select ends_at from public.term_memberships where id=m.id)and(scope<>'unit'or exists(select 1 from public.unit_memberships dep where dep.term_membership_id=recipient.id and dep.unit_id=unit and dep.status='active'and dep.effective_from<=starts and dep.effective_to>=ends))and not exists(select 1 from public.role_assignments src where src.id=c.source_assignment_id and src.scope_type='unit'and not exists(select 1 from public.unit_memberships dep where dep.term_membership_id=m.id and dep.unit_id=src.unit_id and dep.status='active'and dep.effective_from<=starts and dep.effective_to>=ends))))then covered:=true;exit;end if;end loop;
 if not covered then eligible:=false;end if;end loop;
 if not eligible or covered is not true then constraints:=constraints||jsonb_build_array('current_grantor_ceiling_required');end if;
 return jsonb_build_object('withinCeiling',constraints='[]'::jsonb,'mutationAvailable',false,'constraints',constraints,'notice','Validation only. Role/assignment publication and verified replacement enrollment are not implemented in this batch; no authority changed.');end$$;
create function public.explain_my_access(p_term_id uuid,p_work_id uuid default null)returns jsonb language plpgsql stable security definer set search_path='' as $$declare m public.term_memberships;begin m:=app_private.request_actor(p_term_id);return jsonb_build_object('memberId',m.member_id,'grants',coalesce((select jsonb_agg(jsonb_build_object('assignmentId',a.id,'role',r.name,'scope',a.scope_type,'unitId',a.unit_id,'workId',a.work_id,'capability',p.capability,'expiresAt',least(a.effective_to,m.ends_at))order by a.id,p.capability)from public.role_assignments a join public.roles r on r.id=a.role_id join public.role_permissions p on p.role_id=a.role_id and p.allowed_scope=a.scope_type where a.term_id=p_term_id and a.term_membership_id=m.id and app_private.access_assignment_live(a.id)),'[]'),
 'requestedRecordReadable',case when p_work_id is null then null else exists(select 1 from public.work_items w where w.id=p_work_id and w.term_id=p_term_id and public.can_access_work(w.id,'detail'))end,
 'constraints',jsonb_build_array('Current roster, account, role, dates and scope apply.','FIN/MCD/feedback require their separate current designation, case assignment, evidence and independence.','An app role does not grant provider-console ownership.','Emergency access is closed here: recorded approval, reason, expiry and custodian notification require a separately verified path.','No real-user impersonation or sensitive read-all endpoint exists.'));end$$;
create function public.preview_synthetic_access(p_term_id uuid,p_values jsonb)returns jsonb language plpgsql stable security definer set search_path='' as $$declare m public.term_memberships;entry jsonb;begin
 m:=app_private.request_actor(p_term_id);
 if not app_private.definition_keys(p_values,array['scenario','permissions'])or(p_values->>'scenario')is null or(p_values->>'scenario')not in('ordinary_task','finance_case','feedback_case','admin_settings')or jsonb_typeof(p_values->'permissions')is distinct from 'array'or jsonb_array_length(p_values->'permissions')>20 then raise exception using errcode='22023',message='command_validation_failed';end if;
 for entry in select value from jsonb_array_elements(p_values->'permissions')loop if not app_private.definition_keys(entry,array['capability','scope'])or not exists(select 1 from jsonb_array_elements(app_private.access_catalog())x where x->>'capability'=entry->>'capability'and(x->'scopes')?(entry->>'scope'))then raise exception using errcode='22023',message='command_validation_failed';end if;end loop;
 return jsonb_build_object('synthetic',true,'allowsRealAccess',false,'scenario',p_values->>'scenario','fixture','Fictional sample only — no real person, record, amount, feedback or file was queried.','explanation',case p_values->>'scenario'when 'finance_case'then 'A finance capability alone is insufficient: confirmed designation, exact assigned case, current policy/evidence and no self-approval remain mandatory.'when 'feedback_case'then 'A feedback title or capability does not establish a current case/release grant. No PRISM data is loaded.'when 'admin_settings'then 'Configuration and role management are distinct from sensitive data access and provider-console ownership.'else 'Current membership, exact unit/record scope and workflow constraints still apply; no parent/sibling or merge inheritance.'end);end$$;
create function public.read_access_admin(p_term_id uuid)returns jsonb language plpgsql stable security definer set search_path='' as $$declare m public.term_memberships;begin m:=app_private.access_editor(p_term_id);return jsonb_build_object('catalog',app_private.access_catalog(),'mutationAvailable',false,
 'roles',coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'name',r.name,'state',r.state,'version',r.version,'permissions',coalesce((select jsonb_agg(jsonb_build_object('capability',p.capability,'scope',p.allowed_scope)order by p.capability,p.allowed_scope)from public.role_permissions p where p.role_id=r.id),'[]'))order by r.name,r.id)from public.roles r where r.term_id=p_term_id and(public.has_capability(p_term_id,'roles.manage')or not exists(select 1 from public.role_permissions p where p.role_id=r.id and not exists(select 1 from public.delegation_ceilings c where c.term_id=p_term_id and c.grantor_membership_id=m.id and c.capability=p.capability and c.scope_type=p.allowed_scope and app_private.access_ceiling_live(c))))),'[]'),
 'ceilings',coalesce((select jsonb_agg(jsonb_build_object('id',c.id,'capability',c.capability,'scope',c.scope_type,'unitId',c.unit_id,'workId',c.work_id,'expiresAt',c.ends_at,'sensitiveAuthorized',c.sensitive_authorized)order by c.id)from public.delegation_ceilings c where c.term_id=p_term_id and c.grantor_membership_id=m.id and app_private.access_ceiling_live(c)),'[]'),
 'targets',coalesce((select jsonb_agg(jsonb_build_object('id',tm.id,'name',d.display_name)order by d.display_name)from public.read_directory(p_term_id)d join public.term_memberships tm on tm.term_id=p_term_id and tm.member_id=d.member_id),'[]'),
 'units',coalesce((select jsonb_agg(jsonb_build_object('id',u.id,'name',u.name)order by u.name)from public.org_units u where u.term_id=p_term_id and u.archived_at is null),'[]'),
 'records',coalesce((select jsonb_agg(jsonb_build_object('id',x.id,'name',x.name))from(select distinct w.id,case when w.classification='ordinary'then w.title else 'Permitted restricted record'end name from public.delegation_ceilings c join public.work_items w on w.id=c.work_id where c.term_id=p_term_id and c.grantor_membership_id=m.id and app_private.access_ceiling_live(c)and public.can_access_work(w.id,'detail'))x),'[]'),
 'own',public.explain_my_access(p_term_id),'notice','Inspection/preflight foundation only. Publishing roles, assigning/revoking permissions, custody enrollment and audit history remain closed pending the next verified P34 batch.');end$$;
revoke all on function app_private.access_catalog(),app_private.access_assignment_live(uuid),app_private.access_ceiling_live(public.delegation_ceilings),app_private.access_editor(uuid),app_private.access_verified_custodian(uuid)from public,anon,authenticated,service_role;
revoke all on function public.read_access_admin(uuid),public.preflight_access_change(uuid,jsonb),public.explain_my_access(uuid,uuid),public.preview_synthetic_access(uuid,jsonb)from public,anon,authenticated,service_role;
grant execute on function public.read_access_admin(uuid),public.preflight_access_change(uuid,jsonb),public.explain_my_access(uuid,uuid),public.preview_synthetic_access(uuid,jsonb)to authenticated;
